import { useEffect, useState } from "react";

export function PriceTicker({ symbol }: { symbol: string }) {
  const [price, setPrice] = useState<number | null>(null);

  // Keep one subscription in sync with the symbol on screen
  useEffect(() => {
    const unsubscribe = subscribeToPrice(symbol, setPrice);
    return unsubscribe; // stop syncing the old symbol before the next one
  }, [symbol]);

  return <p>{symbol}: {price ?? "…"}</p>;
}
